WITH valid_products AS (SELECT * FROM products WHERE (LOWER(TRIM(product_name)) = 'water bottle' AND MONTH(launch_date) IN (1, 3, 8)) OR UPPER(product_name) LIKE '%UNN%'), agg AS (SELECT brand, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(category))) AS category_values, SUM(CASE WHEN category = 'Fashion' THEN cost ELSE 0 END) AS fashion_cost FROM valid_products GROUP BY brand) SELECT * FROM agg WHERE fashion_cost > 77 ORDER BY fashion_cost;
